import{_ as s,c as l,o as n,at as t}from"./chunks/framework.B-8aa_PR.js";const u=JSON.parse('{"title":"【修正版】在家徒手增肌增重计划 - 详细实施指南","description":"","frontmatter":{},"headers":[],"relativePath":"增肌计划详细指南.md","filePath":"增肌计划详细指南.md","lastUpdated":1771408012000}'),i={name:"增肌计划详细指南.md"};function o(e,a,r,p,g,h){return n(),l("div",null,a[0]||(a[0]=[t(`<h1 id="【修正版】在家徒手增肌增重计划-详细实施指南" tabindex="-1">【修正版】在家徒手增肌增重计划 - 详细实施指南 <a class="header-anchor" href="#【修正版】在家徒手增肌增重计划-详细实施指南" aria-label="Permalink to &quot;【修正版】在家徒手增肌增重计划 - 详细实施指南&quot;">​</a></h1><h2 id="📊-你的个人情况分析" tabindex="-1">📊 你的个人情况分析 <a class="header-anchor" href="#📊-你的个人情况分析" aria-label="Permalink to &quot;📊 你的个人情况分析&quot;">​</a></h2><ul><li><strong>基础代谢</strong>：约1500-1600大卡/天</li><li><strong>日常消耗</strong>：约2000大卡/天</li><li><strong>增肌目标</strong>：每日摄入2400-2600大卡</li><li><strong>现有条件</strong>：新手、居家徒手训练、瑜伽垫+小空间、每周2次训练</li></ul><h2 id="🏋️‍♂️-第一阶段-基础适应期-4-6周" tabindex="-1">🏋️‍♂️ 第一阶段：基础适应期（4-6周） <a class="header-anchor" href="#🏋️‍♂️-第一阶段-基础适应期-4-6周" aria-label="Permalink to &quot;🏋️‍♂️ 第一阶段：基础适应期（4-6周）&quot;">​</a></h2><h3 id="🔄-完全徒手训练方案" tabindex="-1">🔄 完全徒手训练方案 <a class="header-anchor" href="#🔄-完全徒手训练方案" aria-label="Permalink to &quot;🔄 完全徒手训练方案&quot;">​</a></h3><p><strong>训练日A（下肢+核心）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 标准深蹲：3组×10-15次（臀部下蹲至大腿平行）</span></span>
<span class="line"><span>2. 墙壁俯卧撑：3组×8-12次（身体斜靠墙壁完成）</span></span>
<span class="line"><span>3. 仰卧起坐：3组×12-15次（核心基础训练）</span></span>
<span class="line"><span>4. 原地踏步弓步：3组×10次/侧（单腿交替）</span></span>
<span class="line"><span>5. 鸟狗式：3组×8次/侧（核心稳定能力）</span></span></code></pre></div><p><strong>训练日B（上肢+全身）+ 哑铃辅助</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 桌上俯卧撑：3组×8-12次（身体45度角支撑）</span></span>
<span class="line"><span>2. 椅子深蹲：3组×12-15次（臀部轻触椅子站起）</span></span>
<span class="line"><span>3. 简易平板支撑：3组×30-45秒（核心耐力）</span></span>
<span class="line"><span>4. 靠墙俯卧撑下落：3组×8-10次（控制下落速度）</span></span>
<span class="line"><span>5. 简易臀桥：3组×15-20次（臀部激活）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【哑铃增强动作（第二个月后添加）】</span></span>
<span class="line"><span>6. 哑铃侧平举：3组×12-15次（肩部塑造）</span></span>
<span class="line"><span>7. 哑铃弯举：3组×10-12次（手臂增粗）</span></span></code></pre></div><h3 id="🔧-具体执行要点-徒手版" tabindex="-1">🔧 具体执行要点（徒手版） <a class="header-anchor" href="#🔧-具体执行要点-徒手版" aria-label="Permalink to &quot;🔧 具体执行要点（徒手版）&quot;">​</a></h3><p><strong>难度阶梯原则：</strong></p><ul><li>从最简单动作开始：墙壁俯卧撑＞桌上俯卧撑＞标准俯卧撑</li><li>关注姿势标准，而非追求次数</li><li>每月提升动作难度，保持肌肉刺激</li></ul><p><strong>组间休息：60秒-90秒</strong></p><ul><li>复合动作：90秒（深蹲、俯卧撑）</li><li>辅助动作：60秒（核心训练）</li><li>手机计时，严格把控</li></ul><p><strong>训练流程（居家版）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>热身（5分钟）- 关节活动+动态拉伸</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>正式训练（25分钟）- 5个动作×3组</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>拉伸放松（5分钟）- 重点拉伸训练肌群</span></span>
<span class="line"><span>总时长：35分钟左右</span></span></code></pre></div><h3 id="🎯-动作详解与学习资源" tabindex="-1">🎯 动作详解与学习资源 <a class="header-anchor" href="#🎯-动作详解与学习资源" aria-label="Permalink to &quot;🎯 动作详解与学习资源&quot;">​</a></h3><p><strong>学习路径推荐：</strong></p><ol><li>先看YouTube教学视频（搜索关键词见下文）</li><li>对镜练习，检查姿势</li><li>录制视频自我对照</li><li>重点关注容易犯错的技术点</li></ol><p><strong>搜索关键词（中文）：</strong></p><ul><li>&quot;徒手深蹲标准姿势教学&quot;</li><li>&quot;墙壁俯卧撑入门教程&quot;</li><li>&quot;核心训练基础动作&quot;</li><li>&quot;无器械居家训练指南&quot;</li></ul><p><strong>常见错误提醒：</strong></p><ul><li>深蹲时膝盖不过脚尖，腰背挺直</li><li>俯卧撑时身体呈直线，不塌腰</li><li>动作速度要慢，控制更有效</li></ul><h2 id="🍽️-营养实施计划" tabindex="-1">🍽️ 营养实施计划 <a class="header-anchor" href="#🍽️-营养实施计划" aria-label="Permalink to &quot;🍽️ 营养实施计划&quot;">​</a></h2><h3 id="每日饮食结构-以60kg体重为例" tabindex="-1">每日饮食结构（以60kg体重为例） <a class="header-anchor" href="#每日饮食结构-以60kg体重为例" aria-label="Permalink to &quot;每日饮食结构（以60kg体重为例）&quot;">​</a></h3><p><strong>蛋白质（100-120g/天）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>早餐：鸡蛋3个 + 牛奶250ml = 25g蛋白</span></span>
<span class="line"><span>午餐：鸡胸肉200g = 40g蛋白</span></span>
<span class="line"><span>晚餐：鱼肉200g = 35g蛋白</span></span>
<span class="line"><span>加餐：蛋白粉1勺 = 25g蛋白</span></span></code></pre></div><p><strong>碳水（250-300g/天）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>早餐：燕麦片80g + 香蕉1根 = 60g碳水</span></span>
<span class="line"><span>午餐：米饭200g = 60g碳水</span></span>
<span class="line"><span>晚餐：米饭200g = 60g碳水</span></span>
<span class="line"><span>训练前后：香蕉+面包 = 40-60g碳水</span></span>
<span class="line"><span>其他：水果零食等 = 20-30g碳水</span></span></code></pre></div><p><strong>脂肪（50-60g/天）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>烹饪用油15g + 坚果30g + 其他天然脂肪</span></span></code></pre></div><h3 id="具体食谱建议" tabindex="-1">具体食谱建议 <a class="header-anchor" href="#具体食谱建议" aria-label="Permalink to &quot;具体食谱建议&quot;">​</a></h3><p><strong>早餐（7:00-8:00）</strong></p><ul><li>燕麦片80g + 牛奶250ml</li><li>鸡蛋3个（可煎可煮）</li><li>香蕉1根</li></ul><p><strong>上午加餐（10:30）</strong></p><ul><li>坚果一小把（杏仁/核桃）</li><li>全麦面包1片</li></ul><p><strong>午餐（12:00-13:00）</strong></p><ul><li>米饭200g（2小碗）</li><li>鸡胸肉200g（煎或蒸）</li><li>蔬菜任意（无需限制）</li></ul><p><strong>训练前加餐（训练前1小时）</strong></p><ul><li>香蕉1根</li><li>蛋白粉半勺（如需）</li></ul><p><strong>训练后加餐（训练后30分钟内）</strong></p><ul><li>蛋白粉1勺+水</li><li>面包2片或香蕉1根</li></ul><p><strong>晚餐（18:00-19:00）</strong></p><ul><li>米饭200g</li><li>鱼肉/瘦牛肉200g</li><li>蔬菜任意</li></ul><p><strong>睡前加餐（21:00-22:00）</strong></p><ul><li>牛奶250ml</li><li>花生酱1勺或坚果少量</li></ul><h2 id="📈-进度追踪与调整" tabindex="-1">📈 进度追踪与调整 <a class="header-anchor" href="#📈-进度追踪与调整" aria-label="Permalink to &quot;📈 进度追踪与调整&quot;">​</a></h2><h3 id="体重追踪" tabindex="-1">体重追踪 <a class="header-anchor" href="#体重追踪" aria-label="Permalink to &quot;体重追踪&quot;">​</a></h3><ul><li><strong>频率</strong>：每周一早上空腹称重</li><li><strong>记录</strong>：电子表格或手机备忘录</li><li><strong>期望</strong>：每周增重0.25-0.5kg（每月1-2kg）</li></ul><h3 id="动作难度进阶" tabindex="-1">动作难度进阶 <a class="header-anchor" href="#动作难度进阶" aria-label="Permalink to &quot;动作难度进阶&quot;">​</a></h3><ul><li><strong>目标</strong>：每月提升动作难度或增加重复次数</li><li><strong>记录模板</strong>（徒手版）：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>俯卧撑：墙壁→桌上→标准→下斜</span></span>
<span class="line"><span>深蹲：标准→慢速→跳跃→单腿</span></span>
<span class="line"><span>核心：简易平板→标准平板→动态平板</span></span></code></pre></div><h3 id="外观变化-居家版" tabindex="-1">外观变化（居家版） <a class="header-anchor" href="#外观变化-居家版" aria-label="Permalink to &quot;外观变化（居家版）&quot;">​</a></h3><ul><li><strong>照片记录</strong>：每月同一角度、同一光线拍摄上半身</li><li><strong>测量重点</strong>：胸围、臂围、肩宽（容易测量的部位）</li><li><strong>体感变化</strong>：衬衫变紧、皮带位置变化等日常感受</li></ul><h2 id="⚠️-常见问题与解决方案" tabindex="-1">⚠️ 常见问题与解决方案 <a class="header-anchor" href="#⚠️-常见问题与解决方案" aria-label="Permalink to &quot;⚠️ 常见问题与解决方案&quot;">​</a></h2><h3 id="食量不足怎么办" tabindex="-1">食量不足怎么办？ <a class="header-anchor" href="#食量不足怎么办" aria-label="Permalink to &quot;食量不足怎么办？&quot;">​</a></h3><ol><li><strong>分餐制</strong>：三餐变五餐，每餐少吃多餐</li><li><strong>高热量食物</strong>：在食物中添加橄榄油、坚果碎</li><li><strong>流质补充</strong>：奶昔、果汁更容易摄入</li><li><strong>循序渐进</strong>：第一周增加10%食量，慢慢适应</li></ol><h3 id="训练动力不足-徒手训练版" tabindex="-1">训练动力不足？（徒手训练版） <a class="header-anchor" href="#训练动力不足-徒手训练版" aria-label="Permalink to &quot;训练动力不足？（徒手训练版）&quot;">​</a></h3><ol><li><strong>游戏化目标</strong>：挑战连续训练打卡天数</li><li><strong>视频学习</strong>：观看徒手训练高手视频获取灵感</li><li><strong>身体感受</strong>：关注训练后的肌肉泵感和良好状态</li><li><strong>自我竞赛</strong>：与上周的自己比较进步情况</li></ol><h3 id="恢复感觉困难-居家版" tabindex="-1">恢复感觉困难？（居家版） <a class="header-anchor" href="#恢复感觉困难-居家版" aria-label="Permalink to &quot;恢复感觉困难？（居家版）&quot;">​</a></h3><ol><li><strong>睡眠优化</strong>：确保7-8小时高质量休息</li><li><strong>营养补充</strong>：训练后30分钟内补充蛋白+碳水</li><li><strong>活动恢复</strong>：休息日轻度散步或拉伸</li><li><strong>肌肉放松</strong>：自我按摩或热水澡促进恢复</li></ol><h2 id="🔄-阶段过渡标准" tabindex="-1">🔄 阶段过渡标准 <a class="header-anchor" href="#🔄-阶段过渡标准" aria-label="Permalink to &quot;🔄 阶段过渡标准&quot;">​</a></h2><h3 id="何时进入第二-进阶-阶段" tabindex="-1">何时进入第二（进阶）阶段？ <a class="header-anchor" href="#何时进入第二-进阶-阶段" aria-label="Permalink to &quot;何时进入第二（进阶）阶段？&quot;">​</a></h3><p>当满足以下条件时：</p><ul><li>能标准完成墙壁和桌上所有俯卧撑</li><li>深蹲动作稳定，无身体摇晃</li><li>核心力量明显提升，能维持标准平板支撑45秒以上</li><li>体重增加1-2kg，肌肉感受更明显</li></ul><h3 id="何时进入第三-高级-阶段" tabindex="-1">何时进入第三（高级）阶段？ <a class="header-anchor" href="#何时进入第三-高级-阶段" aria-label="Permalink to &quot;何时进入第三（高级）阶段？&quot;">​</a></h3><p>当满足以下条件时：</p><ul><li>能标准完成地面俯卧撑15次以上</li><li>动作难度自然提升，不再满足于基础版本</li><li>身体适应训练节奏，肌肉恢复速度加快</li><li>已经形成固定训练习惯和自信</li></ul><h2 id="💡-徒手训练特别提醒" tabindex="-1">💡 徒手训练特别提醒 <a class="header-anchor" href="#💡-徒手训练特别提醒" aria-label="Permalink to &quot;💡 徒手训练特别提醒&quot;">​</a></h2><ol><li><strong>姿势优先</strong>：动作标准比次数更重要，避免受伤</li><li><strong>循序渐进</strong>：从最简单版本开始，逐步提升难度</li><li><strong>关注感受</strong>：感受目标肌肉的发力，而不是蛮力完成</li><li><strong>融入生活</strong>：把居家训练变成日常习惯，无负担坚持</li><li><strong>自我欣赏</strong>：每个人的进步节奏不同，专注自身变化</li></ol><h2 id="📱-徒手训练实用工具推荐" tabindex="-1">📱 徒手训练实用工具推荐 <a class="header-anchor" href="#📱-徒手训练实用工具推荐" aria-label="Permalink to &quot;📱 徒手训练实用工具推荐&quot;">​</a></h2><p><strong>记录追踪类：</strong></p><ul><li><strong>Keep应用</strong>：内含大量徒手训练视频和计划</li><li><strong>MyFitnessPal</strong>：食物热量记录管理</li><li><strong>备忘录/便签</strong>：简单记录训练次数和进步</li></ul><p><strong>居家辅助类：</strong></p><ul><li><strong>体重秤</strong>：基础体重追踪（无需体脂功能）</li><li><strong>瑜伽垫</strong>：必备的训练保护垫</li><li><strong>镜子</strong>：检查动作姿态的利器</li><li><strong>计时器</strong>：手机自带足够使用</li></ul><p><strong>学习资源类：</strong></p><ul><li><strong>YouTube中文频道</strong>：&quot;肌肉沙滩&quot;、&quot;Pamela Reif&quot;</li><li><strong>抖音健身博主</strong>：学习动作细节和技巧</li><li><strong>Keep教程</strong>：详细的徒手训练分解教学</li></ul><h3 id="💪-哑铃选择建议-第二个月后添加" tabindex="-1">💪 哑铃选择建议（第二个月后添加） <a class="header-anchor" href="#💪-哑铃选择建议-第二个月后添加" aria-label="Permalink to &quot;💪 哑铃选择建议（第二个月后添加）&quot;">​</a></h3><p><strong>推荐配置：</strong></p><ul><li><strong>重量选择</strong>：2.5kg、5kg各一对（总重10-20kg）</li><li><strong>购买渠道</strong>：京东、淘宝搜索&quot;可调节哑铃&quot;</li><li><strong>花费预算</strong>：100-200元人民币</li><li><strong>使用时机</strong>：第二个月熟练掌握基础动作后</li></ul><p><strong>哑铃训练优势：</strong></p><ul><li>显著增强肩部和手臂训练效果</li><li>增加训练多样性和趣味性</li><li>为将来更多器械训练打基础</li><li>提高整体肌肉增长效率</li></ul><p><strong>注意事项：</strong></p><ul><li>从最轻重量开始学习动作</li><li>确保有足够空间安全使用</li><li>配合徒手训练不要完全替代</li></ul><h2 id="🎯-6个月徒手增肌目标" tabindex="-1">🎯 6个月徒手增肌目标 <a class="header-anchor" href="#🎯-6个月徒手增肌目标" aria-label="Permalink to &quot;🎯 6个月徒手增肌目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>体重目标</th><th>训练目标</th><th>外观期望</th></tr></thead><tbody><tr><td>1个月</td><td>+0.5-1kg</td><td>掌握基本动作，建立习惯</td><td>适应期，无显著变化</td></tr><tr><td>3个月</td><td>+2-3kg</td><td>动作质量提升，添加哑铃训练</td><td>胸肌明显，肩臂初显形</td></tr><tr><td>6个月</td><td>+4-6kg</td><td>熟练组合训练，自信提升</td><td>整体变壮，线条清晰</td></tr></tbody></table><h3 id="🌟-真实可行的成果预期" tabindex="-1">🌟 真实可行的成果预期 <a class="header-anchor" href="#🌟-真实可行的成果预期" aria-label="Permalink to &quot;🌟 真实可行的成果预期&quot;">​</a></h3><p><strong>肌肉增长特点：</strong></p><ul><li>徒手训练肌肉增长相对较慢但更扎实</li><li>体型改善主要集中在上半身（胸肩臂）</li><li>核心力量和身体协调性显著提升</li></ul><p><strong>进度指标参考：</strong></p><ul><li><strong>第一个月</strong>：熟悉动作→自信完成基础训练</li><li><strong>前三个月</strong>：肌肉开始显形→训练成为习惯</li><li><strong>前六个月</strong>：体型明显改善→自我形象提升</li></ul><hr><p><strong>记住：徒手训练重在一贯性和坚持。每完成一次训练，你就离目标更近一步！</strong></p><p><em>今天是开始的最佳时机 - 铺开瑜伽垫，开始你的第一次居家训练吧！</em></p>`,94)]))}const c=s(i,[["render",o]]);export{u as __pageData,c as default};
